// Format RSS items for Slack messages
const items = $input.all();

if (items.length === 0) {
  // No new items, stop workflow
  return [];
}

const formatted = items.map(item => {
  const json = item.json;

  // Safely extract and truncate description
  let description = '';
  if (json.description) {
    description = json.description.substring(0, 200);
    if (json.description.length > 200) {
      description += '...';
    }
  }

  // Build Slack-formatted message
  const message = [
    `*${json.title || 'Untitled'}*`,
    description,
    json.link ? `<${json.link}|Read more>` : ''
  ].filter(Boolean).join('\n');

  return {
    json: {
      message: message,
      title: json.title,
      link: json.link,
      guid: json.guid,
      pubDate: json.pubDate
    }
  };
});

return formatted;
